#!/usr/bin/env python3
"""Generate deployment/deployment-settings.example.json.

The shape mirrors what `pac solution create-settings` emits for a solution's
connection references and environment variables, so the operator can hand the
filled-in copy to `pac solution import --settings-file` (or transcribe from
it) instead of typing 24 values into the import dialog from memory.

Every value ships BLANK on purpose. The operator copies this file to an
untracked `deployment-settings.dod.json`, fills in the real connection IDs
and the 24 environment values on the .mil side, and never commits it -- the
repository is public and real site URLs, tenant IDs and connection IDs must
not exist in it. The example is regenerated by build_bundle.sh so it can
never drift from configuration/, and tests/test_operator_bundle_selfcontained
fails the release if any value is non-blank.
"""
import json
import os
import sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CFG = os.path.join(ROOT, "configuration")


def build():
    with open(os.path.join(CFG, "environment-variables.json"),
              encoding="utf-8") as fh:
        env = json.load(fh)["environmentVariables"]
    with open(os.path.join(CFG, "connection-references.json"),
              encoding="utf-8") as fh:
        con = json.load(fh)["connectionReferences"]
    return {
        "_instructions": (
            "Copy to deployment-settings.dod.json (NEVER committed - the "
            "repository is public), fill every Value and ConnectionId on "
            "the .mil side, then import with: pac solution import --path "
            "MissionFeedingOperations_1.0.0.zip --settings-file "
            "deployment-settings.dod.json. deployment/site-bindings.md is "
            "the worksheet the values come from."),
        "EnvironmentVariables": [
            {"SchemaName": v["schemaName"], "Value": ""} for v in env
        ],
        "ConnectionReferences": [
            {"LogicalName": c["schemaName"],
             "ConnectionId": "",
             "ConnectorId": c["connectorId"]} for c in con
        ],
    }


def main():
    out = os.path.join(ROOT, "deployment",
                       "deployment-settings.example.json")
    data = build()
    with open(out, "w", encoding="utf-8") as fh:
        json.dump(data, fh, indent=2)
        fh.write("\n")
    print(f"wrote {os.path.relpath(out, ROOT)}: "
          f"{len(data['EnvironmentVariables'])} environment variables, "
          f"{len(data['ConnectionReferences'])} connection references, "
          f"all values blank")
    return 0


if __name__ == "__main__":
    sys.exit(main())
